/* The legacy struct tags generated by protoc-gen-go, ported from google.golang.org/protobuf
 * v1.36.12 internal/encoding/tag/tag.go (Marshal) and internal/encoding/defval/default.go
 * (Marshal with the GoTag format). */
#ifndef GO_TAG_H
#define GO_TAG_H

#include "protodesc.h"

/* Marshal encodes the field descriptor as a tag. enum_name (may be NULL) must be provided if the
 * kind is an enum. The result may contain any bytes of the default value of a string field. */
Str tag_marshal(const GoField *fd, const char *enum_name);

/* defval.Marshal(v, ev, k, GoTag): the default value in the Go struct tag format, or NULL if it
 * cannot be formatted. */
const char *tag_marshal_default(const GoValue *v, int kind, Str *out);

#endif
